type_list_int32() -> {<<"List">>, [{<<"Int32">>, []}]}.

make_cons(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Cons">>, Fields, type_list_int32(), Schema).

make_nil(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Nil">>, Fields, type_list_int32(), Schema).
